package com.aprax.aidesignstudio.adapters;
import android.view.*; import android.widget.TextView; import androidx.recyclerview.widget.RecyclerView; import com.aprax.aidesignstudio.R;
public class TemplateAdapter extends RecyclerView.Adapter<TemplateAdapter.Holder> { private final String[] items={"Modern Landing Page","SaaS Dashboard","Mobile App UI","Portfolio Website","E-commerce Store"}; public Holder onCreateViewHolder(ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_template,p,false));} public void onBindViewHolder(Holder h,int pos){h.title.setText(items[pos]);h.desc.setText("AI-ready template");} public int getItemCount(){return items.length;} static class Holder extends RecyclerView.ViewHolder{TextView title,desc;Holder(View v){super(v);title=v.findViewById(R.id.tv_title);desc=v.findViewById(R.id.tv_description);}} }